; c07_alu_status -- the flags of ALU_STATUS
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: which bit of ALU_STATUS[0] is which flag (D4); which bit 'negative' takes for a logic result (D5)
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c07_alu_status.expected.csv
.include "conf_defs.inc"
.main
    MOV CONST(0x0000, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0000, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU AND
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 0, len=1, ptr=8
    MOV CONST(0x8000, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0000, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU OR
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 1, len=1, ptr=8
    MOV CONST(0x8000, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0000, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU SHL 1 unsigned
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 2, len=1, ptr=8
    MOV CONST(0xFFFF, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0001, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU ADD unsigned
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 3, len=1, ptr=8
    MOV CONST(0x0003, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0007, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU SUB unsigned
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 4, len=1, ptr=8
    MOV CONST(0x7FFF, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0001, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU ADD signed
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 5, len=1, ptr=8
    MOV CONST(0x0001, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0001, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU ADD unsigned
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 6, len=1, ptr=8
    MOV CONST(0x0005, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0005, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU CMP.EQ unsigned
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 7, len=1, ptr=8
    MOV CONST(0x0001, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(0x0001, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU ADD unsigned
    MOV ALU_STATUS[0..0] -> MAIN_SCRATCHPAD[8..8]
    EXEC_CSR WRITE_SP RES + 8, len=1, ptr=8
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
